var t=`1062-mee-goreng-mamak`;var a=`world-1062`;var n=`MY`;var s=`southeast-asia`;var r=4;var o=27;var g={en:`Mee Goreng Mamak`,ua:`Мі горенг мамак`};var l={en:`Mee Goreng Mamak is a dish from Malaysia prepared with egg noodles, garlic, shallot, shrimp. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Мі горенг мамак, страва кухні країни Малайзія, яку готують із таких продуктів: яєчна локшина, часник, цибуля шалот, креветка. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var m=[{en:`Cook the listed ingredients in simmering water for about 6 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 6 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:6,i:[[`egg-noodles`,440,`g`],[`water`,1e3,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`garlic`,5,`clove`],[`shallot`,140,`g`],[`canola-oil`,40,`ml`],[`shrimp`,280,`g`],[`tofu-firm`,240,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`tomato`,240,`g`],[`green-bell-pepper`,170,`g`],[`sweet-soy-sauce-kecap-manis`,45,`ml`],[`chili-garlic-sauce`,30,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lime`,2,`pcs`],[`cilantro`,20,`g`]]}];var d={slug:t,id:a,country:`MY`,region:s,servings:4,minutes:27,title:g,text:l,steps:m};export{n as country,d as default,a as id,o as minutes,s as region,r as servings,t as slug,m as steps,l as text,g as title};